changeSet.sql:

if not exists (select 1 from [sys].[key_constraints] where name = 'PK_MetricRollupPathLink')
begin
	ALTER TABLE [metrics].[RollupPathLink] ADD CONSTRAINT [PK_MetricRollupPathLink] PRIMARY KEY CLUSTERED ( [RollupPathUid] ASC, [StartPosition] ASC )
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricAssetVersionConditionItem_MetricRollupPath')
begin
	ALTER TABLE [metrics].[RollupPathLink]  WITH CHECK ADD  CONSTRAINT [FK_MetricAssetVersionConditionItem_MetricRollupPath] FOREIGN KEY([RollupPathUid]) REFERENCES [metrics].[RollupPath] ([Uid]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[RollupPathLink] CHECK CONSTRAINT [FK_MetricAssetVersionConditionItem_MetricRollupPath];
end

if not exists (select 1 from [INFORMATION_SCHEMA].[REFERENTIAL_CONSTRAINTS] where constraint_name = 'FK_MetricRollupPathLink_IntersectType')
begin
	ALTER TABLE [metrics].[RollupPathLink]  WITH CHECK ADD  CONSTRAINT [FK_MetricRollupPathLink_IntersectType] FOREIGN KEY([IntersectTypeID]) REFERENCES [dbo].[IntersectType] ([ID]) ON DELETE CASCADE;
	ALTER TABLE [metrics].[RollupPathLink] CHECK CONSTRAINT [FK_MetricRollupPathLink_IntersectType];
end
